begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(18);
select set_config('request.jwt.claim.role','service_role',true);
create temporary table m18_result as select public.erp_prepare_pilot_provisioning_v1('{"idempotencyKey":"pilot:staging:m18-g17-synthetic","slug":"m18-g17-synthetic","domain":"m18-g17-synthetic.connectioncyber.invalid","displayName":"Empresa Sintetica M18","vertical":"retail","legalName":"EMPRESA SINTETICA SEM VALOR FISCAL","tradeName":"PILOTO SINTETICO","cnpj":"00000000000000","stateRegistration":"ISENTO","establishmentCode":"HQ","ownerSubjectKey":"synthetic-owner","ownerEmailRef":"protected:M18_SYNTHETIC_EMAIL","capabilities":["core.parties","core.catalog","inventory.stock","sales.pos","finance"]}'::jsonb)result;
select ok(not(result->>'replayed')::boolean,'first preparation is not replay')from m18_result;
select is((select count(*)::integer from public.tenants where slug='m18-g17-synthetic'),1,'one synthetic tenant created');
select is((select count(*)::integer from public.erp_establishments e join public.tenants t on t.id=e.tenant_id where t.slug='m18-g17-synthetic'and e.state_registration='ISENTO'),1,'synthetic establishment stores IE');
select is((select count(*)::integer from public.erp_roles r join public.tenants t on t.id=r.tenant_id where t.slug='m18-g17-synthetic'and r.key='owner'and r.requires_mfa and r.sensitivity='privileged'),1,'owner is privileged and MFA protected');
select ok((select count(*)>0 from public.erp_role_permissions rp join public.tenants t on t.id=rp.tenant_id where t.slug='m18-g17-synthetic'),'owner receives permission bindings');
select is((select count(*)::integer from public.erp_tenant_capabilities c join public.tenants t on t.id=c.tenant_id where t.slug='m18-g17-synthetic'and c.status='active'),5,'five capabilities activated');
select is((select count(*)::integer from public.erp_auth_invitation_outbox o join public.tenants t on t.id=o.tenant_id where t.slug='m18-g17-synthetic'and o.status='pending'),1,'one pending invitation enqueued');
select is((select count(*)::integer from public.erp_identity_provisioning_runs where idempotency_key='pilot:staging:m18-g17-synthetic'and status='running'),1,'run waits for Auth');
select is((select count(*)::integer from public.erp_identity_provisioning_steps s join public.erp_identity_provisioning_runs r on r.id=s.run_id where r.idempotency_key='pilot:staging:m18-g17-synthetic'),6,'six durable steps recorded');
select is((select count(*)::integer from public.erp_tenant_memberships m join public.tenants t on t.id=m.tenant_id where t.slug='m18-g17-synthetic'),0,'membership waits for Auth identity');
select ok((public.erp_prepare_pilot_provisioning_v1('{"idempotencyKey":"pilot:staging:m18-g17-synthetic","slug":"m18-g17-synthetic","domain":"m18-g17-synthetic.connectioncyber.invalid","displayName":"Empresa Sintetica M18","vertical":"retail","legalName":"EMPRESA SINTETICA SEM VALOR FISCAL","tradeName":"PILOTO SINTETICO","cnpj":"00000000000000","stateRegistration":"ISENTO","establishmentCode":"HQ","ownerSubjectKey":"synthetic-owner","ownerEmailRef":"protected:M18_SYNTHETIC_EMAIL","capabilities":["core.parties","core.catalog","inventory.stock","sales.pos","finance"]}'::jsonb)->>'replayed')::boolean,'identical replay succeeds');
select is((select count(*)::integer from public.erp_auth_invitation_outbox o join public.tenants t on t.id=o.tenant_id where t.slug='m18-g17-synthetic'),1,'replay does not duplicate outbox');
select throws_ok($$select public.erp_prepare_pilot_provisioning_v1('{"idempotencyKey":"pilot:staging:m18-g17-synthetic","slug":"other-synthetic","domain":"other.connectioncyber.invalid","displayName":"Outro","vertical":"retail","legalName":"OUTRO","tradeName":"OUTRO","cnpj":"11111111111111","stateRegistration":"OUTRA","establishmentCode":"HQ","ownerSubjectKey":"synthetic-owner","ownerEmailRef":"protected:M18_SYNTHETIC_EMAIL","capabilities":["finance"]}'::jsonb)$$,'23505','idempotency conflict','divergent replay rejected');
select throws_ok($$select public.erp_prepare_pilot_provisioning_v1('{"idempotencyKey":"pilot:staging:m18-g17-secret","slug":"secret-synthetic","domain":"secret.connectioncyber.invalid","displayName":"Sintetica","vertical":"retail","legalName":"SINTETICA","tradeName":"SINTETICA","cnpj":"22222222222222","stateRegistration":"ISENTO","establishmentCode":"HQ","ownerSubjectKey":"synthetic-owner","ownerEmailRef":"protected:M18_SYNTHETIC_EMAIL","capabilities":["finance"],"password":"blocked"}'::jsonb)$$,'22023','unsafe provisioning request','secret key rejected');
select throws_ok($$select public.erp_prepare_pilot_provisioning_v1('{"idempotencyKey":"pilot:staging:m18-g17-unknown","slug":"unknown-synthetic","domain":"unknown.connectioncyber.invalid","displayName":"Sintetica","vertical":"retail","legalName":"SINTETICA","tradeName":"SINTETICA","cnpj":"33333333333333","stateRegistration":"ISENTO","establishmentCode":"HQ","ownerSubjectKey":"synthetic-owner","ownerEmailRef":"protected:M18_SYNTHETIC_EMAIL","capabilities":["finance"],"unexpected":true}'::jsonb)$$,'22023','unsafe provisioning request','unknown key rejected');
select set_config('request.jwt.claim.role','authenticated',true);
select throws_ok($$select public.erp_prepare_pilot_provisioning_v1('{}'::jsonb)$$,'42501','broker only','authenticated caller rejected');
select set_config('request.jwt.claim.role','service_role',true);
select ok(not exists(select 1 from public.erp_auth_invitation_outbox where email_ref!~'^protected:'),'outbox stores protected references only');
select is((select count(*)::integer from public.erp_auth_identity_compensations),0,'no compensation created before Auth');
select*from finish();rollback;
